export const listAssignmentsResponseIdRegExp = new RegExp('^\\d{4}-\\d{2}-\\d{2}_[a-z0-9]{1,40}_[A-Z0-9]{2,20}$');
export const listAssignmentsResponseBusIdRegExp = new RegExp('^[A-Z0-9]{2,20}$');
export const listAssignmentsResponseServiceDateRegExp = new RegExp('^\\d{4}-\\d{2}-\\d{2}$');


export const ListAssignmentsResponseItem = zod.object({
  "id": zod.string().regex(listAssignmentsResponseIdRegExp),
  "driverUid": zod.string(),
  "driverEmail": zod.string().describe('Copied from the membership when saved, so conflict messages can name people'),
  "busId": zod.string().regex(listAssignmentsResponseBusIdRegExp),
  "routeId": zod.string().uuid(),
  "routeVersion": zod.number().int().nullable().describe('The route\'s published version when the assignment was saved; informational, Start pins its own'),
  "shift": zod.string().describe('The route\'s shift at save time'),
  "serviceDate": zod.string().regex(listAssignmentsResponseServiceDateRegExp).describe('Calendar date in Asia/Kolkata'),
  "startsAt": zod.number().describe('IST midnight opening the service date, epoch milliseconds'),
  "endsAt": zod.number().describe('startsAt + 24h'),
  "createdAt": zod.number(),
  "createdBy": zod.string()
}).describe('A dated override of the standing bus (ASG-01); the key is serviceDate_shiftKey_busId under the driver')
export const ListAssignmentsResponse = zod.array(ListAssignmentsResponseItem)


